def transform(g):
    h, w = len(g), len(g[0])
    rectangles = []
    for r0 in range(h):
        for color in set(g[r0]):
            valid = [g[r0][c] == color for c in range(w)]
            for r1 in range(r0, h):
                if r1 > r0:
                    valid = [valid[c] and g[r1][c] == color for c in range(w)]
                if r1-r0+1 < 5:
                    continue
                c = 0
                while c < w:
                    if not valid[c]:
                        c += 1
                        continue
                    a = c
                    while c < w and valid[c]:
                        c += 1
                    b = c-1
                    if b-a+1 < 5:
                        continue
                    extend_top = r0 > 0 and all(g[r0-1][x] == color for x in range(a,b+1))
                    extend_bottom = r1+1 < h and all(g[r1+1][x] == color for x in range(a,b+1))
                    extend_left = a > 0 and all(g[y][a-1] == color for y in range(r0,r1+1))
                    extend_right = b+1 < w and all(g[y][b+1] == color for y in range(r0,r1+1))
                    if not (extend_top or extend_bottom or extend_left or extend_right):
                        rectangles.append((r0,r1,a,b))
    out=[row[:] for row in g]
    for r0,r1,c0,c1 in rectangles:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1): out[r][c]=4
    return out
